text:
When we started Marquez Family Home Care, we wanted to understand our neighbors before we knocked on a single door. Who in our community needs help at home, and what kind of help? We went to the U.S. Census Bureau’s American Community Survey for answers.
We looked at two groups we care for:
The Census doesn’t ask whether someone “needs a caregiver.” It asks about specific difficulties, and two of them line up closely with non-medical home care:
Show the R code
library(tidyverse)
library(tidycensus)
library(scales)
library(knitr)

# ACS 5-year vintage. 2024 = the 2020–2024 survey. Drop to 2023 if load_variables() errors.
acs_year &lt;- 2024

# Neighborhoods within a reasonable drive of our home base in 92122 (ZIP code tabulation areas)
service_area &lt;- tribble(
  ~zcta,   ~area,
  "92122", "University City",
  "92037", "La Jolla",
  "92117", "Clairemont",
  "92111", "Linda Vista / Kearny Mesa",
  "92123", "Serra Mesa",
  "92124", "Tierrasanta",
  "92126", "Mira Mesa",
  "92121", "Sorrento Valley",
  "92130", "Carmel Valley",
  "92129", "Rancho Peñasquitos",
  "92131", "Scripps Ranch",
  "92109", "Pacific Beach",
  "92110", "Bay Park / Morena",
  "92108", "Mission Valley",
  "92120", "Allied Gardens / Del Cerro",
  "92119", "San Carlos",
  "92128", "Rancho Bernardo",
  "92014", "Del Mar"
)
service_zips &lt;- service_area$zcta

if (Sys.getenv("CENSUS_API_KEY") == "") {
  stop("No Census API key found. Run tidycensus::census_api_key('YOUR_KEY', install = TRUE) and restart R.")
}

# Brand colors for charts
brand &lt;- list(
  forest   = "#0f3e17",
  petal    = "#79b88b",
  burgundy = "#7a1f3d",
  cream    = "#fffefc",
  charcoal = "#222222",
  mist     = "#efeeeb"
)

band_labels &lt;- c(u18 = "Under 18", a18_64 = "Adults 18–64", s65 = "Seniors 65+")
band_colors &lt;- c("Adults 18–64" = brand$petal, "Seniors 65+" = brand$forest)
measure_labels &lt;- c(
  any       = "Any disability",
  selfcare  = "Self-care difficulty\n(bathing, dressing)",
  indliving = "Independent-living difficulty\n(errands, appointments)"
)

theme_marquez &lt;- function(base_size = 12) {
  theme_minimal(base_size = base_size) +
    theme(
      text               = element_text(color = brand$charcoal),
      plot.title         = element_text(color = brand$forest, size = base_size + 3),
      plot.title.position = "plot",
      plot.subtitle      = element_text(color = brand$charcoal),
      plot.caption       = element_text(color = brand$charcoal, size = base_size - 3, hjust = 0),
      plot.caption.position = "plot",
      axis.text          = element_text(color = brand$charcoal),
      panel.grid.minor   = element_blank(),
      panel.grid.major.y = element_blank(),
      panel.grid.major.x = element_line(color = brand$mist),
      legend.position    = "top",
      legend.justification = "left",
      plot.background    = element_rect(fill = brand$cream, color = NA),
      panel.background   = element_rect(fill = brand$cream, color = NA)
    )
}
Show the R code
acs_vars &lt;- load_variables(acs_year, "acs5", cache = TRUE) |&gt;
  select(name, label) |&gt;
  mutate(label = str_remove_all(label, ":"))

acs_pull &lt;- function(level = c("county", "zcta"), table = NULL, variables = NULL) {
  level &lt;- match.arg(level)
  args &lt;- list(year = acs_year, survey = "acs5")
  if (!is.null(table))     args$table &lt;- table
  if (!is.null(variables)) args$variables &lt;- variables
  args &lt;- if (level == "county") {
    c(args, geography = "county", state = "CA", county = "San Diego")
  } else {
    c(args, list(geography = "zcta", zcta = service_zips))
  }
  out &lt;- do.call(get_acs, args)
  if (!is.null(table)) out &lt;- left_join(out, acs_vars, by = c("variable" = "name"))
  out
}

last_part &lt;- function(label) word(label, -1, sep = "!!")

age_band &lt;- function(age) {
  case_when(
    age %in% c("Under 18 years", "5 to 17 years")                          ~ "u18",
    age %in% c("18 to 34 years", "35 to 64 years", "18 to 64 years")       ~ "a18_64",
    age %in% c("65 to 74 years", "75 years and over", "65 years and over") ~ "s65",
    TRUE ~ NA_character_
  )
}

# Population by age (B01001)
age_counts &lt;- function(level) {
  acs_pull(level, table = "B01001") |&gt;
    filter(str_count(label, "!!") == 3) |&gt;
    mutate(
      age_txt = last_part(label),
      age_lo  = if_else(str_detect(age_txt, "^Under"), 0,
                        as.numeric(str_extract(age_txt, "\\d+")))
    ) |&gt;
    group_by(GEOID, NAME) |&gt;
    summarise(
      pop_total = sum(estimate),
      pop_18_64 = sum(estimate[age_lo &gt;= 18 & age_lo &lt; 65]),
      pop_65    = sum(estimate[age_lo &gt;= 65]),
      pop_75    = sum(estimate[age_lo &gt;= 75]),
      pop_85    = sum(estimate[age_lo &gt;= 85]),
      .groups = "drop"
    )
}

# Disability / difficulty status by age band (C18108, B18106, B18107), parsed by label
status_by_age &lt;- function(level, table, leaf_pattern, without_pattern) {
  acs_pull(level, table = table) |&gt;
    filter(str_detect(last_part(label), leaf_pattern)) |&gt;
    mutate(
      age  = str_extract(label, "Under 18 years|\\d+ to \\d+ years|\\d+ years and over"),
      band = age_band(age),
      has  = !str_detect(last_part(label), without_pattern)
    ) |&gt;
    filter(!is.na(band)) |&gt;
    group_by(GEOID, band) |&gt;
    summarise(
      with     = sum(estimate[has]),
      with_moe = moe_sum(moe[has], estimate[has]),
      universe = sum(estimate),
      .groups  = "drop"
    ) |&gt;
    mutate(pct = with / universe)
}

status_long &lt;- function(level) {
  bind_rows(
    any       = status_by_age(level, "C18108", "disability", "^No disability"),
    selfcare  = status_by_age(level, "B18106", "difficulty", "^No "),
    indliving = status_by_age(level, "B18107", "difficulty", "^No "),
    .id = "measure"
  )
}

status_wide &lt;- function(long) {
  long |&gt;
    select(GEOID, measure, band, with, pct) |&gt;
    pivot_wider(names_from = c(measure, band), values_from = c(with, pct),
                names_glue = "{measure}_{band}_{.value}")
}

# Seniors living alone (B09020)
living_alone &lt;- function(level) {
  acs_pull(level, table = "B09020") |&gt;
    group_by(GEOID) |&gt;
    summarise(
      pop65_universe = estimate[variable == "B09020_001"],
      alone_65       = sum(estimate[str_detect(label, regex("living alone$", ignore_case = TRUE))]),
      .groups = "drop"
    ) |&gt;
    mutate(pct_alone_65 = alone_65 / pop65_universe)
}

# Spanish spoken at home among people 65+ (B16004)
spanish_65 &lt;- function(level) {
  acs_pull(level, table = "B16004") |&gt;
    group_by(GEOID) |&gt;
    summarise(
      pop65_lang = sum(estimate[str_detect(label, "!!65 years and over$")]),
      spanish_65 = sum(estimate[str_detect(label, "65 years and over!!Speak Spanish$")]),
      .groups = "drop"
    ) |&gt;
    mutate(pct_spanish_65 = spanish_65 / pop65_lang)
}

build_profile &lt;- function(level) {
  long &lt;- status_long(level)
  wide &lt;- list(age_counts(level), status_wide(long), living_alone(level), spanish_65(level)) |&gt;
    reduce(left_join, by = "GEOID")
  list(wide = wide, long = long)
}
Show the R code
county_raw &lt;- build_profile("county")
zip_raw    &lt;- build_profile("zcta")

county      &lt;- county_raw$wide
county_long &lt;- county_raw$long
zips        &lt;- zip_raw$wide |&gt; left_join(service_area, by = c("GEOID" = "zcta"))
zip_long    &lt;- zip_raw$long |&gt; left_join(service_area, by = c("GEOID" = "zcta"))

# When the numbers were pulled from the Census API (kept with the frozen results)
data_pulled  &lt;- Sys.Date()
pulled_label &lt;- sprintf("%s %d, %s", format(data_pulled, "%B"),
                        as.integer(format(data_pulled, "%d")), format(data_pulled, "%Y"))
acs_label    &lt;- paste0("American Community Survey ", acs_year - 4, "–", acs_year, " 5-year estimates")
source_caption &lt;- paste0("Source: U.S. Census Bureau, ", acs_label, ". Data pulled ", pulled_label, ".")
